def twos(x, n):
    if x < -2**(n-1) or x > 2**(n-1) - 1:
        return 'overflow'
    if x < 0:
        x += 2**n
    return format(x, '0' + str(n) + 'b')

def from_twos(s):
    n = len(s)
    v = int(s, 2)
    if s[0] == '1':
        v -= 2**n
    return v

def add_signed(a, b, n):
    s = (int(a, 2) + int(b, 2)) % (2**n)
    r = format(s, '0' + str(n) + 'b')
    ovf = a[0] == b[0] and r[0] != a[0]
    return (r, ovf)

