pr.solution:
def rle(s):
    out = ''
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out += str(j - i) + s[i]
        i = j
    return out

def ratio(s):
    return round(len(s) / len(rle(s)), 2)
